(() => {
  const STOCK_CSV = __STOCK_CSV__;
  const PRICE_HISTORY = __PRICE_HISTORY__;

  const stockRows = d3.csvParse(STOCK_CSV);
  const priceTickers = new Set(Object.keys(PRICE_HISTORY));

  const data = stockRows
    .map((row) => {
      const ticker = (row.ticker || '').trim();
      const sector = (row.sector || 'Unclassified').trim();
      const name = (row['full name'] || '').trim();
      const marketCap = Number(row.marketCap);
      return {
        ticker,
        sector,
        name,
        marketCap: Number.isFinite(marketCap) ? marketCap : null
      };
    })
    .filter((row) => row.ticker && priceTickers.has(row.ticker));

  const sectors = Array.from(new Set(data.map((d) => d.sector)));
  const colors = d3.quantize(d3.interpolateSpectral, Math.max(3, sectors.length)).reverse();
  const colorScale = d3.scaleOrdinal().domain(sectors).range(colors);

  const caps = data.filter((d) => d.marketCap).map((d) => d.marketCap);
  const capExtent = d3.extent(caps.length ? caps : [1]);
  const radiusScale = d3.scaleSqrt().domain(capExtent).range([14, 48]);

  data.forEach((d) => {
    d.isEtf = !d.marketCap;
    d.radius = d.isEtf ? 20 : radiusScale(d.marketCap);
  });

  const chartEl = document.getElementById('bubble-chart');
  const legendEl = document.getElementById('legend');
  const tableBody = d3.select('#stock-table tbody');
  const tooltip = d3.select('#tooltip');

  function formatMarketCap(value) {
    if (!value) return 'N/A';
    const abs = Math.abs(value);
    if (abs >= 1e12) return `${(value / 1e12).toFixed(2)}T`;
    if (abs >= 1e9) return `${(value / 1e9).toFixed(2)}B`;
    if (abs >= 1e6) return `${(value / 1e6).toFixed(2)}M`;
    return value.toLocaleString();
  }

  function buildLegend() {
    const legend = d3.select(legendEl);
    legend.selectAll('*').remove();
    const items = legend
      .selectAll('.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    items
      .append('span')
      .attr('class', 'legend-swatch')
      .style('background', (d) => colorScale(d));

    items.append('span').attr('class', 'legend-label').text((d) => d);
  }

  function renderTable(rows) {
    const sorted = [...rows].sort((a, b) => {
      if (!a.marketCap && !b.marketCap) return a.ticker.localeCompare(b.ticker);
      if (!a.marketCap) return 1;
      if (!b.marketCap) return -1;
      return b.marketCap - a.marketCap;
    });

    const tr = tableBody
      .selectAll('tr')
      .data(sorted, (d) => d.ticker);

    const trEnter = tr.enter().append('tr');

    trEnter.append('td').attr('class', 'cell-ticker');
    trEnter.append('td').attr('class', 'cell-name');
    trEnter.append('td').attr('class', 'cell-sector');
    trEnter.append('td').attr('class', 'cell-cap');

    const trMerge = trEnter.merge(tr);
    trMerge.select('.cell-ticker').text((d) => d.ticker);
    trMerge.select('.cell-name').text((d) => d.name);
    trMerge.select('.cell-sector').text((d) => d.sector);
    trMerge.select('.cell-cap').text((d) => formatMarketCap(d.marketCap));

    tr.exit().remove();

    trMerge.on('click', (event, d) => {
      setSelected(d.ticker);
    });
  }

  let svg;
  let nodeGroup;
  let textGroup;
  let simulation;
  let selectedTicker = null;

  function computeSectorCenters(width, height) {
    const columns = Math.ceil(Math.sqrt(sectors.length));
    const rows = Math.ceil(sectors.length / columns);
    const spanX = width * 0.55;
    const spanY = height * 0.55;
    const xScale = d3.scalePoint().domain(d3.range(columns)).range([width / 2 - spanX / 2, width / 2 + spanX / 2]);
    const yScale = d3.scalePoint().domain(d3.range(rows)).range([height / 2 - spanY / 2, height / 2 + spanY / 2]);

    const centers = {};
    sectors.forEach((sector, i) => {
      const col = i % columns;
      const row = Math.floor(i / columns);
      centers[sector] = {
        x: xScale(col),
        y: yScale(row)
      };
    });
    return centers;
  }

  function renderChart() {
    const rect = chartEl.getBoundingClientRect();
    const width = Math.max(320, rect.width);
    const height = Math.max(460, rect.height);
    const centers = computeSectorCenters(width, height);

    d3.select(chartEl).selectAll('svg').remove();
    svg = d3
      .select(chartEl)
      .append('svg')
      .attr('width', width)
      .attr('height', height)
      .attr('viewBox', `0 0 ${width} ${height}`);

    nodeGroup = svg.append('g').attr('class', 'nodes');

    const nodes = nodeGroup
      .selectAll('g')
      .data(data, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node')
      .on('mouseover', (event, d) => showTooltip(event, d))
      .on('mousemove', (event) => moveTooltip(event))
      .on('mouseout', () => hideTooltip())
      .on('click', (event, d) => {
        setSelected(d.ticker);
      });

    nodes
      .append('circle')
      .attr('r', (d) => d.radius)
      .attr('fill', (d) => colorScale(d.sector))
      .attr('class', 'bubble');

    nodes
      .append('text')
      .attr('class', 'bubble-label')
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .text((d) => d.ticker)
      .style('font-size', (d) => `${Math.max(9, d.radius / 2.6)}px`);

    simulation = d3
      .forceSimulation(data)
      .force(
        'x',
        d3.forceX((d) => centers[d.sector].x).strength(0.25)
      )
      .force(
        'y',
        d3.forceY((d) => centers[d.sector].y).strength(0.25)
      )
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collide', d3.forceCollide((d) => d.radius + 2))
      .force('charge', d3.forceManyBody().strength(-5))
      .on('tick', () => {
        nodes.attr('transform', (d) => `translate(${d.x}, ${d.y})`);
      });
  }

  function showTooltip(event, d) {
    if (d.isEtf) return;
    tooltip.classed('hidden', false);
    tooltip.html(`
      <div class="tt-title">${d.ticker}</div>
      <div class="tt-name">${d.name}</div>
      <div class="tt-sector">${d.sector}</div>
      <div class="tt-sparkline"></div>
    `);

    const history = PRICE_HISTORY[d.ticker];
    if (history && history.length) {
      const sparkline = tooltip.select('.tt-sparkline');
      const parseDate = d3.timeParse('%Y-%m-%d');
      const values = history
        .map((item) => ({
          date: parseDate(item.date),
          value: item.close
        }))
        .filter((item) => item.date && Number.isFinite(item.value));

      const width = 160;
      const height = 52;
      const svg = sparkline
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', `0 0 ${width} ${height}`);

      const xScale = d3
        .scaleTime()
        .domain(d3.extent(values, (v) => v.date))
        .range([6, width - 6]);
      const yScale = d3
        .scaleLinear()
        .domain(d3.extent(values, (v) => v.value))
        .nice()
        .range([height - 8, 6]);

      const line = d3
        .line()
        .x((v) => xScale(v.date))
        .y((v) => yScale(v.value))
        .curve(d3.curveMonotoneX);

      svg
        .append('path')
        .datum(values)
        .attr('d', line)
        .attr('fill', 'none')
        .attr('stroke', '#f05a28')
        .attr('stroke-width', 2);
    }

    moveTooltip(event);
  }

  function moveTooltip(event) {
    tooltip
      .style('left', `${event.pageX + 14}px`)
      .style('top', `${event.pageY - 24}px`);
  }

  function hideTooltip() {
    tooltip.classed('hidden', true);
  }

  function setSelected(ticker) {
    selectedTicker = ticker;
    d3.selectAll('.node').classed('selected', (d) => d.ticker === ticker);
    d3.selectAll('#stock-table tbody tr').classed('selected', (d) => d.ticker === ticker);

    const row = document.querySelector(`#stock-table tbody tr[data-ticker="${ticker}"]`);
    if (row) {
      row.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }
  }

  function syncTableData() {
    d3.selectAll('#stock-table tbody tr').attr('data-ticker', (d) => d.ticker);
  }

  renderTable(data);
  syncTableData();
  buildLegend();
  renderChart();

  window.addEventListener('resize', () => {
    renderChart();
  });
})();
JS"}

